        eUnitType = UNIT_OBJECT;
        CUnit::CreateMissileOrMonster(0x1de, D2Common::Units::GetXPosFromDynamicPathUnit(pDynamicPath), D2Common::Units::GetYPosFromDynamicPathUnit(pDynamicPath), eUnitType, nZero);
